const BASE_NEED={home:['homeRankings','afterSales','homeProfit','productTrafficDaily','financeData'],orders:['orders','homeRankings'],returns:['afterSales','orders'],products:['linksData','homeRankings'],inventory:['inventoryTrend','linksData'],traffic:['productTrafficDaily','linksData'],reviews:['comments'],marketing:['linksData','actions','financeData'],ops:['actions','linksData'],system:[]};
const NEED=BASE_NEED;
const S={tab:'home',q:'',scope:'ALL',start:'',end:'',rangePreset:'today',rangeOpen:false,calendarStartMonth:'',calendarEndMonth:'',trendMetric:'sales',salesMode:'net',qtyMode:'net',returnsMode:'request',profitMode:'loss',metric:'sales',core:'idle',err:''},D={},SS={},P={};
const RMB_RATE=1.8;
const $=id=>document.getElementById(id);
const H=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const N=v=>{const n=Number(v??0);return Number.isFinite(n)?n:0};
const M=v=>N(v).toLocaleString('zh-CN',{maximumFractionDigits:0});
