function needsFor(tab=S.tab){return tab==='home'?homeNeeds():(BASE_NEED[tab]||[])}
function surl(n){return (location.protocol==='http:'||location.protocol==='https:')?'/api/bi/section/'+encodeURIComponent(n):'../sections/'+encodeURIComponent(n)+'.json'}async function core(){S.core='loading';render();try{const r=await fetch('../data.json?ts='+Date.now(),{cache:'no-store'});if(!r.ok)throw Error('core HTTP '+r.status);merge(await r.json());S.core='ok';S.err='';dates(true);render();ensure(S.tab,true)}catch(e){S.core='error';S.err=e?.message||String(e);render()}}async function load(n,silent=false,force=false){if(SS[n]?.status==='ok'&&!force)return true;if(SS[n]?.status==='error'&&!force)return false;if(P[n])return P[n];SS[n]={status:'loading',error:''};if(!silent)render();P[n]=fetch(surl(n),{cache:'no-store'}).then(async r=>{if(!r.ok)throw Error('HTTP '+r.status);
const j=await r.json();if(j&&j.ok===false)throw Error(j.error||'section failed');const expected=D.__sections?.generatedAt||D.generatedAt||'';if(expected&&j.generatedAt&&j.generatedAt!==expected)throw Error(n+' generatedAt 不匹配：section='+j.generatedAt+' core='+expected);merge(j);dates(false);SS[n]={status:'ok',error:'',generatedAt:j.generatedAt||''};delete P[n];render();return true}).catch(e=>{SS[n]={status:'error',error:e?.message||String(e)};delete P[n];render();return false});return P[n]}

function ensure(tab=S.tab,silent=false){needsFor(tab).forEach(n=>load(n,silent))}

function chips(ns){return'<div class="sects">'+(ns||[]).map(n=>{const s=SS[n]?.status||'idle',c=s==='ok'?'ok':s==='loading'?'loading-chip':s==='error'?'bad':'';return`<span class="${c}" title="${H(SS[n]?.error||'')}">${H(SL[n]||n)} · ${s==='ok'?'已就绪':s==='loading'?'加载中':s==='error'?'失败':'待加载'}</span>`}).join('')+'</div>'}

function wait(n,t='正在从云端 section API 加载数据…'){const s=SS[n]||{};if(s.status==='error')return`<div class="error"><b>${H(SL[n]||n)} 加载失败</b><br>${H(s.error)}<p><button class="btn" data-load="${H(n)}">重试</button></p></div>`;load(n,true);return`<div class="loading"><span class="spin"></span><span>${H(t)}</span></div>`}

function collectDates(){const ds=[];
[D.dates?.salesDate,D.dates?.businessDate,D.dates?.linkDate].forEach(v=>{const d=ISO(v);if(d)ds.push(d)});
[...A(D.rankings?.dailyStores),...A(D.rankings?.dailyStoreProducts),...A(D.rankings?.dailyProducts),...A(D.homeProfitSummary?.dailyScopes),...A(D.profit?.dailyStoreProducts),...A(D.afterSales),...A(D.orders),...A(D.productTrafficDaily),...A(D.inventoryTrend),...A(D.inventoryDepletion?.visibleTrend)].forEach(r=>{const d=dt(r);if(d)ds.push(d)});
return ds.filter(Boolean).sort()}

function dataAnchorDate(){return collectDates().at(-1)||ISO(new Date().toISOString())}

function computePresetRange(key,anchor=dataAnchorDate()){const a=ISO(anchor)||ISO(new Date().toISOString());const m=monthStart(a);switch(String(key||'today')){case'yesterday':return{start:addDateDays(a,-1),end:addDateDays(a,-1)};case'last3':return{start:addDateDays(a,-2),end:a};case'last7':return{start:addDateDays(a,-6),end:a};case'last15':return{start:addDateDays(a,-14),end:a};case'last30':return{start:addDateDays(a,-29),end:a};case'thisMonth':return{start:m,end:a};case'lastMonth':{const s=addMonths(m,-1);return{start:s,end:monthEnd(s)}}case'last3Months':return{start:addMonths(m,-2),end:a};case'lastYear':return{start:addDateDays(a,-364),end:a};case'today':default:return{start:a,end:a}}}

function calendarMonthStart(dateText){return monthStart(dateText||dataAnchorDate())}
