function applyPreset(key){const r=computePresetRange(key,dataAnchorDate());S.rangePreset=key;S.start=r.start;S.end=r.end;S.rangeOpen=false;S.calendarStartMonth=calendarMonthStart(r.start);S.calendarEndMonth=calendarMonthStart(r.end===r.start?addCalendarMonths(r.start,1):r.end)}
function dates(force=false){if(!force&&S.start&&S.end)return;applyPreset(S.rangePreset||'today')}
function preset(days){const map={1:'today',3:'last3',7:'last7',15:'last15',30:'last30',365:'lastYear'};applyPreset(map[Number(days)]||'last7');sync(false);render();ensure(S.tab,true)}

function renderCalendarPanel(monthDate,role){const first=parseDateOnly(calendarMonthStart(monthDate))||new Date();const y=first.getFullYear(),m=first.getMonth();const offset=(first.getDay()+6)%7;const gridStart=new Date(y,m,1-offset);const days=[];for(let i=0;i<42;i++){const d=new Date(gridStart.getFullYear(),gridStart.getMonth(),gridStart.getDate()+i);const iso=isoDate(d);const cls=['calendar-day',d.getMonth()===m?'':'out',iso>=S.start&&iso<=S.end?'in-range':'',iso===S.start?'start':'',iso===S.end?'end':''].filter(Boolean).join(' ');days.push(`<button type="button" class="${cls}" data-calendar-date="${H(iso)}" data-calendar-role="${H(role)}">${d.getDate()}</button>`)}return `<div class="range-calendar-panel"><div class="calendar-panel-head"><div><span class="sub">${role==='start'?'开始时间':'结束时间'}</span><h4>${H(monthTitle(monthDate))}</h4></div><div class="calendar-nav"><button type="button" data-calendar-shift="${H(role)}" data-calendar-delta="-1">‹</button><button type="button" data-calendar-shift="${H(role)}" data-calendar-delta="1">›</button></div></div><div class="calendar-week"><span>一</span><span>二</span><span>三</span><span>四</span><span>五</span><span>六</span><span>日</span></div><div class="calendar-days">${days.join('')}</div></div>`}
function rangeControl(){dates(false);if(!S.calendarStartMonth)S.calendarStartMonth=calendarMonthStart(S.start);if(!S.calendarEndMonth)S.calendarEndMonth=calendarMonthStart(S.end===S.start?addCalendarMonths(S.start,1):S.end);const presets=[['today','今天'],['yesterday','昨天'],['last3','近3天'],['last7','近7天'],['last15','近15天'],['last30','近30天'],['thisMonth','本月'],['lastMonth','上个月'],['last3Months','近3个月'],['lastYear','近一年']];const label=(presets.find(x=>x[0]===S.rangePreset)||['custom','自定义'])[1];return `<div class="range-toolbar"><div class="range-toolbar-main"><button type="button" class="range-button" data-range-toggle="1" aria-expanded="${S.rangeOpen?'true':'false'}"><span>时间筛选</span><div><strong>${H(selectedRangeText())}</strong><small>${H(label)} · 影响 KPI、趋势、排行和明细</small></div></button><div class="range-preset-strip">${presets.map(([k,l])=>`<button type="button" class="${S.rangePreset===k?'active':''}" data-range-preset="${H(k)}">${H(l)}</button>`).join('')}</div></div><div class="range-popover" ${S.rangeOpen?'':'hidden'}><div class="calendar-input-row"><label class="calendar-input-card"><span>开始日期</span><input id="rangeStart" type="text" inputmode="numeric" value="${H(S.start)}" placeholder="YYYY-MM-DD"></label><label class="calendar-input-card"><span>结束日期</span><input id="rangeEnd" type="text" inputmode="numeric" value="${H(S.end)}" placeholder="YYYY-MM-DD"></label></div><div class="range-calendar-grid">${renderCalendarPanel(S.calendarStartMonth,'start')}${renderCalendarPanel(S.calendarEndMonth,'end')}</div><div class="calendar-pick-note">左侧选开始，右侧选结束；也可以直接输入日期。快捷时间不用打开弹窗。</div></div></div>`}

