function trafficLooseByScope(){const q=String(S.q||'').trim().toLowerCase(),set=scopeStores(),all=S.scope==='ALL';return A(D.productTrafficDaily||[]).filter(r=>{const st=sk(r);if(st&&!set.has(st))return false;if(!st&&!all)return false;if(q){const short=/^[a-z0-9-]{1,4}$/i.test(q);const fields=short?[pkey(r),prod(r),r?.goods_title]:[pkey(r),prod(r),r?.goods_title,r?.skc,r?.sku];const hay=fields.map(x=>String(x||'').toLowerCase()).join('|');if(!hay.includes(q))return false}return true})}

