function invTrendLoose(){const q=String(S.q||'').trim().toLowerCase();return A(D.inventoryTrend||D.inventoryDepletion?.visibleTrend||[]).filter(r=>{const d=dt(r);if(d&&S.start&&d<S.start)return false;if(d&&S.end&&d>S.end)return false;if(q){const hay=[pkey(r),prod(r),r.goods_title].join('|').toLowerCase();if(!hay.includes(q))return false}return true})}

