function netSales(r){return firstNum(r,['sales_sar','net_revenue_sar','known_net_revenue_sar'])}
function grossSales(r){return firstNum(r,['gross_sales_sar','gross_revenue_sar','known_gross_revenue_sar'])||netSales(r)}
