function trafficSummary(allowLatest=true){let rows=traffic();let fallback=false,latestAvailable=false;if(!rows.length&&allowLatest){const loose=trafficLooseByScope();const latestDate=collectDatesFromRows(loose).at(-1)||'';if(latestDate){rows=loose.filter(r=>dt(r)===latestDate);latestAvailable=true}}if(!rows.length&&S.scope==='ALL'&&!String(S.q||'').trim()&&A(D.trend?.linkSeries).length){rows=A(D.trend.linkSeries).filter(r=>{const d=dt(r);return(!S.start||d>=S.start)&&(!S.end||d<=S.end)});fallback=true}const exp=sumFirst(rows,['eps_uv','exposure_uv','exposure_cnt','impressions']);const uv=sumFirst(rows,['goods_uv','uv','visitor_cnt','visitors']);const sale=sumFirst(rows,['sale_cnt','pay_order_cnt','quantity']);const latest=[...rows].sort((a,b)=>String(dt(a)).localeCompare(String(dt(b)))).at(-1)||{};const click=exp?uv/exp:firstNum(latest,['avg_click_rate','click_rate']);const pay=uv?sale/uv:firstNum(latest,['avg_pay_rate','pay_rate']);return{rows,exp,uv,sale,click,pay,fallback,latestAvailable,latestDate:dt(latest)}}
function inventoryScopeNote(){return S.q?'当前货号筛选；库存不按店铺/负责人拆分':'库存不按店铺/负责人拆分，仅货号搜索生效'}
function inventorySummary(){const rows=invProducts();const totalSupply=sumFirst(rows,['estimated_total_supply_quantity','total_supply_quantity']);const daily=sumFirst(rows,['weighted_daily_gross_sales','daily_sales','gross_sold_30d'])/(rows.some(r=>r.weighted_daily_gross_sales!=null)?1:30);const snap=collectDatesFromRows(rows).at(-1)||D.dates?.inventoryDate||D.dates?.etUpdatedAt||'';return{rows,count:rows.length,available:sumFirst(rows,['et_estimated_available_qty','available_qty']),onhand:sumFirst(rows,['estimated_on_hand_quantity','on_hand_quantity']),incoming:sumFirst(rows,['incoming_quantity']),totalSupply,daily,days:daily>0?totalSupply/daily:null,snapshot:snap}}
function collectDatesFromRows(rows){return A(rows).map(dt).filter(Boolean).sort()}

function intro(t,c){return`<section class="intro"><div><span class="eyebrow"><i></i>${H(t)}</span><h2>${H(t)}</h2><p>${H(c)}</p></div><div class="badge">${H(selectedRangeText())} · ${H(scopeName())}${S.q?' · '+H(S.q):''}</div></section>`}

function head(t,c,e=''){return`<div class="head"><div><h3>${H(t)}</h3><p>${H(c)}</p></div>${e}</div>`}

function table(headers,rows){return`<div class="table-wrap"><table><thead><tr>${headers.map(h=>`<th>${H(h)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map((c,i)=>`<td class="${i>2?'num':''}">${String(c).includes('<span')?c:H(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}

function panel(t,sub,heads,rows){return`<section class="panel"><h4>${H(t)}</h4><p class="sub">${H(sub)}</p>${rows.length?table(heads,rows):'<div class="empty">当前筛选没有明细。</div>'}</section>`}

function trend(rows,field){const m=new Map();for(const r of rows){const d=dt(r);if(d)m.set(d,(m.get(d)||0)+N(r[field]))}return Array.from(m,([date,value])=>({date,value})).sort((a,b)=>a.date.localeCompare(b.date))}

function trendFirst(rows,fields){const m=new Map();for(const r of rows){const d=dt(r);if(d)m.set(d,(m.get(d)||0)+firstNum(r,fields))}return Array.from(m,([date,value])=>({date,value})).sort((a,b)=>a.date.localeCompare(b.date))}

function chart(rows){const top=Math.max(...rows.map(r=>Math.abs(N(r.value))),1);return`<div class="chart">${rows.slice(-60).map(r=>`<div class="vbar" title="${H(r.date+' · '+M2(r.value))}" style="height:${Math.max(2,Math.abs(N(r.value))/top*100)}%"></div>`).join('')}</div>`}

function homeRankList(items,opt={}){if(!items.length)return'<div class="empty">当前筛选没有排行数据。</div>';const max=Math.max(1,...items.map(x=>Math.abs(N(x.value))));return`<div class="rank-list ${H(opt.className||'')}">${items.slice(0,opt.limit||18).map((it,i)=>{const pct=Math.max(4,Math.round(Math.abs(N(it.value))/max*100));const color=opt.color?opt.color(it):it.color||'var(--accent)';const attr=opt.attr?opt.attr(it):'';return`<button class="rank-item" ${attr} style="--bar-color:${H(color)}" title="${H(it.label||it.key||'-')}"><span class="rank-no">${i+1}</span><span class="rank-main"><span class="rank-name">${H(it.label||it.key||'-')}</span><span class="rank-meta">${H(it.meta||it.sub||'')}</span><i style="width:${pct}%"></i></span><span class="rank-value">${H(it.valueText||M(it.value))}<small>${H(it.subValue||'')}</small></span></button>`}).join('')}</div>`}
function rank(items,kind=''){if(!items.length)return'<div class="empty">当前筛选没有排行数据。</div>';return`<div class="rank">${items.slice(0,18).map((it,i)=>{const o=kind==='store'?ownByStore.get(it.key):null;return`<div class="rank-row"><span class="muted">${i+1}</span><div><b>${H(it.label||it.key)}</b><small>${H(it.sub||it.meta||'')}</small></div><div class="num"><b>${M(it.value)}</b><br>${o?`<span class="owner"><i class="dot" style="background:${H(o.color||'#7357ff')}"></i>${H(o.name)}</span>`:`<span class="tiny">${H(it.note||it.valueText||'')}</span>`}</div></div>`}).join('')}</div>`}

function averageNetUnitPriceText(r){const q=N(r.quantity);return '均价 '+(q?M2(N(r.sales_sar)/q):'—')+' SAR'}
function storeRanks(){return Array.from(grp(sales(),r=>sk(r)),([key,rs])=>{const sales=rs.reduce((a,r)=>a+netSales(r),0),qty=rs.reduce((a,r)=>a+netQty(r),0),orders=rs.reduce((a,r)=>a+netOrders(r),0),days=uniq(rs.map(dt)).length;const o=ownByStore.get(key);return{key,label:key,value:sales,sales_sar:sales,quantity:qty,orders,days,color:o?.color,meta:`${o?.name?o.name+' · ':''}${averageNetUnitPriceText({sales_sar:sales,quantity:qty})} · 订单 ${M(orders)} · 销量 ${M(qty)} 件 · ${M(days)} 天`,valueText:money(sales),subValue:rmb(sales)}}).sort((a,b)=>b.value-a.value)}
function storeQtyRanks(){return storeRanks().map(x=>({...x,value:x.quantity,valueText:M(x.quantity)+' 件',subValue:money(x.sales_sar),meta:`${ownByStore.get(x.key)?.name?ownByStore.get(x.key).name+' · ':''}${averageNetUnitPriceText(x)} · 订单 ${M(x.orders)} · 净成交 ${money(x.sales_sar)} · ${M(x.days)} 天`})).sort((a,b)=>b.value-a.value)}
function productRanks(){return Array.from(grp(psales(),r=>pkey(r)),([key,rs])=>{const sales=rs.reduce((a,r)=>a+netSales(r),0),qty=rs.reduce((a,r)=>a+netQty(r),0),orders=rs.reduce((a,r)=>a+netOrders(r),0),stores=uniq(rs.map(sk)).length,days=uniq(rs.map(dt)).length;return{key,label:prod(rs[0]),value:sales,sales_sar:sales,quantity:qty,orders,stores,days,meta:`${averageNetUnitPriceText({sales_sar:sales,quantity:qty})} · 销量 ${M(qty)} 件 · 订单 ${M(orders)} · 覆盖 ${M(stores)} 店 · ${M(days)} 天`,valueText:money(sales),subValue:rmb(sales)}}).sort((a,b)=>b.value-a.value)}
function productQtyRanks(){return productRanks().map(x=>({...x,value:x.quantity,valueText:M(x.quantity)+' 件',subValue:money(x.sales_sar),meta:`${averageNetUnitPriceText(x)} · 净成交 ${money(x.sales_sar)} · 订单 ${M(x.orders)} · 覆盖 ${M(x.stores)} 店 · ${M(x.days)} 天`})).sort((a,b)=>b.value-a.value)}

function metricMatrix(heads,rows,cols){return`<div class="metric-matrix cols-${cols}">${heads.map(h=>`<div class="matrix-cell head">${H(h)}</div>`).join('')}${rows.map(r=>`<div class="matrix-cell label">${H(r.label)}</div>${r.cells.map(c=>`<div class="matrix-cell value">${c}</div>`).join('')}`).join('')}</div>`}
function metricCard(title,sub,heads,rows,tip){return`<article class="overview-matrix-card"><div class="matrix-card-head"><h4>${H(title)} <em class="help" title="${H(tip||'')}">?</em></h4><div class="sub">${H(sub)}</div></div>${metricMatrix(heads,rows,Math.max(1,heads.length-1))}</article>`}
function homeKpis(){const s=salesSummary(),req=retRequestSummary(),ordRet=retOrderSummary(),p=profSum(),tr=trafficSummary(),iv=inventorySummary();const rankingsLoading=sourceLoading('homeRankings',s.rows);const afterLoading=sourceLoading('afterSales',req.rows);const profitLoading=sourceLoading(String(S.q||'').trim()?'profit':'homeProfit',p.rows);const trafficLoading=sourceLoading('productTrafficDaily',tr.rows);const invLoading=sourceLoading('financeData',iv.rows);const active=v=>v==null?'—':M(v)+' 个';const profitLoss=p.loss,profitRtv=p.rtv;return`<section class="kpi-six">`+
metricCard('当前时段成交额',selectedRangeText()+' · '+homeScopeSubtitle(),['口径','SAR','RMB'],[
{label:'总成交额',cells:[htmlValue(money(s.gross),rankingsLoading),htmlValue(rmb(s.gross),rankingsLoading)]},
{label:'净成交额',cells:[htmlValue(money(s.net),rankingsLoading),htmlValue(rmb(s.net),rankingsLoading)]}], '总成交额是原始成交规模；净成交额扣除退货、仅退款、派送失败等反转订单。')+
metricCard('当前时段订单 / 销量 / 动销',selectedRangeText()+' · '+homeScopeSubtitle(),['口径','订单','销量','动销货号'],[
{label:'总订单/销量',cells:[htmlValue(M(s.gord)+' 单',rankingsLoading),htmlValue(M(s.gqty)+' 件',rankingsLoading),htmlValue(active(s.gactive),rankingsLoading)]},
{label:'净订单/销量',cells:[htmlValue(M(s.ord)+' 单',rankingsLoading),htmlValue(M(s.qty)+' 件',rankingsLoading),htmlValue(active(s.active),rankingsLoading)]}], '总订单/销量看原始出单；净订单/销量看最终仍保留成交额的订单。')+
metricCard('当前时段退货 / 售后',selectedRangeText()+' · 双口径',['口径','数量','SAR','RMB'],[
{label:'售后申请时间',cells:[htmlValue(M(req.cases)+' 单',afterLoading),htmlValue(money(req.amount),afterLoading),htmlValue(rmb(req.amount),afterLoading)]},
{label:'订单创建时间',cells:[htmlValue(M(ordRet.cases)+' 单',rankingsLoading),htmlValue(money(ordRet.amount),rankingsLoading),htmlValue(rmb(ordRet.amount),rankingsLoading)]}], '申请时间用于发现当天售后异常；订单创建时间用于和订单成熟窗口复盘。')+
metricCard('当前时段真实利润',selectedRangeText()+' · 双测算',['口径','SAR','RMB','利润率'],[
{label:'退货全损保守',cells:[htmlValue(money(profitLoss),profitLoading),htmlValue(rmb(profitLoss),profitLoading),htmlValue(PCT(p.revenue?profitLoss/p.revenue:null),profitLoading)]},
{label:'RTV入仓测算',cells:[htmlValue(money(profitRtv),profitLoading),htmlValue(rmb(profitRtv),profitLoading),htmlValue(PCT(p.revenue?profitRtv/p.revenue:null),profitLoading)]}], '仓储费已进入真实利润；货号搜索时优先使用完整 profit section，避免拿全店利润冒充货号利润。')+
metricCard('当前时段流量',selectedRangeText()+' · 日期×店铺×货号',['指标','数值','说明'],[
{label:'曝光量',cells:[htmlValue(M(tr.exp),trafficLoading),htmlValue(tr.rows.length?(tr.latestAvailable?((tr.latestDate||'最新')+' · 最新可用'):(tr.fallback?'core 宽表':'productTrafficDaily 精确聚合')):'暂无明细',trafficLoading)]},
{label:'访客量',cells:[htmlValue(M(tr.uv),trafficLoading),htmlValue('点击率 '+PCT(tr.click),trafficLoading)]},
{label:'成交件数',cells:[htmlValue(M(tr.sale),trafficLoading),htmlValue('支付率 '+PCT(tr.pay),trafficLoading)]},
{label:'最新日期',cells:[htmlValue(tr.latestDate||'—',trafficLoading),htmlValue(tr.latestAvailable?'选定期无明细，显示同筛选最新可用':(tr.fallback?'宽表 fallback':'按筛选重算'),trafficLoading)]}], '流量按当前日期、店铺/负责人、货号搜索聚合；点击率/支付率按分子分母重算。')+
metricCard('当前库存 / 去化','当前快照 · '+inventoryScopeNote(),['指标','数值','说明'],[
{label:'货号数',cells:[htmlValue(M(iv.count)+' 个',invLoading),htmlValue(inventoryScopeNote(),invLoading)]},
{label:'ET可售',cells:[htmlValue(M(iv.available)+' 件',invLoading),htmlValue('ET实盘；不与在途相加',invLoading)]},
{label:'成本表在库',cells:[htmlValue(M(iv.onhand)+' 件',invLoading),htmlValue(shortDate(iv.snapshot),invLoading)]},
{label:'成本表在途',cells:[htmlValue(M(iv.incoming)+' 件',invLoading),htmlValue('已发未完整到仓/计费',invLoading)]},
{label:'成本表供给',cells:[htmlValue(M(iv.totalSupply)+' 件',invLoading),htmlValue('到仓 + 在途 - 已售',invLoading)]},
{label:'去化周期',cells:[htmlValue(iv.days==null?'—':M2(iv.days)+' 天',invLoading),htmlValue(iv.daily>0?'按 '+M2(iv.daily)+' 件/天':'无动销速度',invLoading)]}], '去化周期按总供给/加权日销汇总，不平均各货号天数。')+'</section>'}

const TREND_METRICS={sales:{label:'成交额',money:true},quantity:{label:'销量'},returns:{label:'售后'},profit:{label:'利润',money:true},traffic:{label:'流量'},inventory:{label:'库存'}};
function trendMetricButtons(){return`<div class="trend-toggle">${Object.entries(TREND_METRICS).map(([k,m])=>`<button type="button" class="${S.trendMetric===k?'active':''}" data-trend-metric="${H(k)}">${H(m.label)}</button>`).join('')}</div>`}
function bucketLabel(id,kind){return kind==='month'?id:id}
function bucket(map,id,kind){const row=map.get(id)||{id,label:bucketLabel(id,kind)};map.set(id,row);return row}
function rowsFromMap(map){return Array.from(map.values()).sort((a,b)=>String(a.id).localeCompare(String(b.id)))}
function addTrend(map,kind,date,vals){if(!date)return;const id=kind==='month'?monthId(date):date;const r=bucket(map,id,kind);Object.entries(vals).forEach(([k,v])=>r[k]=N(r[k])+N(v))}
function buildTrendSeries(kind,metric=S.trendMetric){const map=new Map();if(metric==='sales'||metric==='quantity'){for(const r of sales()){const d=dt(r);addTrend(map,kind,d,metric==='sales'?{net:netSales(r),gross:grossSales(r)}:{net:netQty(r),gross:grossQty(r)})}return{series:rowsFromMap(map),lines:[{key:'net',label:metric==='sales'?'净成交额':'净销量',color:metric==='sales'?'#10b981':'#60a5fa'},{key:'gross',label:metric==='sales'?'总成交额':'总销量',color:metric==='sales'?'#f59e0b':'#a78bfa'}],note:'按当前店铺/负责人、货号和日期筛选重算。'}}
if(metric==='returns'){for(const r of sales()){const d=dt(r);addTrend(map,kind,d,{order:Math.max(0,grossOrders(r)-netOrders(r))})}for(const r of returns()){const d=ISO(r.request_time||dt(r));addTrend(map,kind,d,{request:1})}return{series:rowsFromMap(map),lines:[{key:'request',label:'售后申请时间',color:'#ef4444'},{key:'order',label:'订单创建时间',color:'#f97316'}],note:'申请时间来自售后明细；订单创建时间来自总订单与净订单差额。'}}
if(metric==='profit'){for(const r of hprofit()){const d=dt(r);addTrend(map,kind,d,{loss:profitAmountLoss(r),rtv:profitAmountRtv(r)})}return{series:rowsFromMap(map),lines:[{key:'loss',label:'退货全损保守',color:'#14b8a6'},{key:'rtv',label:'RTV入仓测算',color:'#f97316'}],note:'含仓储真实利润；两条线与顶部利润卡同口径。'}}
if(metric==='traffic'){for(const r of trafficSummary(false).rows){const d=dt(r);addTrend(map,kind,d,{eps:firstNum(r,['eps_uv','exposure_uv','exposure_cnt','impressions']),uv:firstNum(r,['goods_uv','uv','visitor_cnt','visitors']),sale:firstNum(r,['sale_cnt','pay_order_cnt','quantity'])})}return{series:rowsFromMap(map),lines:[{key:'eps',label:'曝光量',color:'#06b6d4'},{key:'uv',label:'访客量',color:'#3b82f6'},{key:'sale',label:'成交件数',color:'#8b5cf6'}],note:'绝对量同轴展示；点击率/支付率留在顶部流量卡。'}}
if(metric==='inventory'){const latestByMonth=new Map();for(const r of invTrendLoose()){const d=dt(r);if(!d)continue;const id=kind==='month'?monthId(d):d;const row=latestByMonth.get(id)||{id,label:id,date:''};if(!row.date||d>=row.date){row.date=d;row.usable=firstNum(r,['usable_inventory','platform_display_stock','available_qty']);row.total=firstNum(r,['inventory_quantity','total_inventory','platform_total_stock']);row.locked=firstNum(r,['order_locked_quantity','pay_locked_quantity','locked_inventory'])}latestByMonth.set(id,row)}return{series:rowsFromMap(latestByMonth),lines:[{key:'usable',label:'可售展示库存',color:'#14b8a6'},{key:'total',label:'总展示库存',color:'#60a5fa'},{key:'locked',label:'锁定库存',color:'#f59e0b'}],note:(kind==='month'?'月图取每月最新快照，不累加库存。':'来自前台展示库存每日快照。')}}
return{series:[],lines:[],note:''}}
function trendValueText(v,metric=S.trendMetric){const meta=TREND_METRICS[metric]||{};return meta.money?money(v):M(v)}
function niceCeil(v){const n=Math.abs(N(v));if(n<=10)return 10;const p=Math.pow(10,Math.floor(Math.log10(n)));return Math.ceil(n/p)*p}
function lineChart(kind,metric=S.trendMetric){const built=buildTrendSeries(kind,metric),series=built.series||[],lines=built.lines||[];const meta=TREND_METRICS[metric]||{};if(!series.length||!lines.length)return`<div class="empty">当前时间段 ${H(selectedRangeText())} 暂无${H(meta.label||metric)}趋势数据。</div>`;const keys=lines.map(x=>x.key),colors=Object.fromEntries(lines.map(x=>[x.key,x.color])),labels=Object.fromEntries(lines.map(x=>[x.key,x.label]));const vals=series.flatMap(r=>keys.map(k=>N(r[k])));const maxRaw=Math.max(1,...vals),minRaw=Math.min(0,...vals);const max=niceCeil(maxRaw),min=minRaw<0?-niceCeil(Math.abs(minRaw)):0,span=Math.max(1,max-min);const w=1280,h=286,padL=72,padR=26,padT=24,padB=48;const xFor=i=>series.length===1?(padL+w-padR)/2:padL+i/(series.length-1)*(w-padL-padR);const yFor=v=>padT+(1-((N(v)-min)/span))*(h-padT-padB);const ticks=[min,min+span*.25,min+span*.5,min+span*.75,max];const grid=ticks.map(v=>`<line class="grid-line" x1="${padL}" y1="${yFor(v).toFixed(1)}" x2="${w-padR}" y2="${yFor(v).toFixed(1)}"></line><text class="axis" text-anchor="end" x="${padL-8}" y="${(yFor(v)+4).toFixed(1)}">${H(compact(v))}</text>`).join('');const polys=keys.map(k=>{const pts=series.map((r,i)=>`${xFor(i).toFixed(1)},${yFor(r[k]).toFixed(1)}`).join(' ');const dots=series.map((r,i)=>`<circle class="dot" cx="${xFor(i).toFixed(1)}" cy="${yFor(r[k]).toFixed(1)}" r="3.5" fill="${colors[k]}"><title>${H(labels[k]+' '+r.label+' '+trendValueText(r[k],metric))}</title></circle>`).join('');return`<polyline class="series" points="${pts}" stroke="${colors[k]}"></polyline>${dots}`}).join('');const every=series.length<=7?1:Math.ceil(series.length/5);const valueLabels=keys.map((k,ki)=>series.map((r,i)=>{if(!(i===0||i===series.length-1||i%every===0))return'';const v=N(r[k]);if(!v&&i!==0&&i!==series.length-1)return'';const x=xFor(i),y=Math.max(14,yFor(v)-8-ki*12),anchor=i===0?'start':i===series.length-1?'end':'middle';return`<text class="value-label" text-anchor="${anchor}" x="${x.toFixed(1)}" y="${y.toFixed(1)}" fill="${colors[k]}">${H(compact(v))}</text>`}).join('')).join('');const axis=series.map((r,i)=>(series.length<=8||i===0||i===series.length-1||i%Math.ceil(series.length/6)===0)?`<text class="axis" text-anchor="${i===0?'start':i===series.length-1?'end':'middle'}" x="${xFor(i).toFixed(1)}" y="${h-8}">${H(r.label)}</text>`:'').join('');const latest=series.at(-1)||{};return`<div class="line-chart"><svg viewBox="0 0 ${w} ${h}" role="img" aria-label="${H((kind==='month'?'月':'日')+(meta.label||metric)+'趋势')}">${grid}<line class="axis-line" x1="${padL}" y1="${padT}" x2="${padL}" y2="${h-padB}"></line><line class="axis-line" x1="${padL}" y1="${h-padB}" x2="${w-padR}" y2="${h-padB}"></line>${polys}${valueLabels}${axis}</svg><div class="chart-legend">${keys.map(k=>`<span><i style="--c:${colors[k]}"></i>${H(labels[k])}：${H(trendValueText(latest[k]||0,metric))}</span>`).join('')}</div><p class="sub">时间段：${H(S.start)} 至 ${H(S.end)}；当前显示 ${M(series.length)} 个${kind==='month'?'月份':'日期'}。${H(built.note||'')}</p></div>`}
function trendPanel(kind){const metric=S.trendMetric;const needed=metric==='profit'?(String(S.q||'').trim()?'profit':'homeProfit'):metric==='traffic'?'productTrafficDaily':metric==='inventory'?'inventoryTrend':'homeRankings';const built=buildTrendSeries(kind,metric);if(sourceLoading(needed,built.series))return`<section class="panel trend-panel"><h4>${kind==='month'?'月趋势':'日趋势'} · ${H(TREND_METRICS[metric]?.label||metric)}</h4><p class="sub">${H(SL[needed]||needed)} 加载中</p><div class="empty">正在加载${H(SL[needed]||needed)}，加载完成后自动刷新本图。</div></section>`;return`<section class="panel trend-panel"><h4>${kind==='month'?'月趋势':'日趋势'} · ${H(TREND_METRICS[metric]?.label||metric)}</h4><p class="sub">${H(metric==='inventory'?inventoryScopeNote():homeScopeSubtitle())}</p>${lineChart(kind,metric)}</section>`}

function auditHtml(){const a=D.audit;if(!a)return'<span class="audit-warn">未找到体检文件</span>';if(a.ok&&!a.warnings&&!a.errors)return'<span class="audit-ok">通过</span>';if(a.errors)return`<span class="audit-bad">${H(a.errors)} 个错误</span>`;return`<span class="audit-warn">${H(a.warnings||0)} 个提醒</span>`}
function healthStrip(){const dates=D.dates||{};const costTs=dates.manualCostFileUpdatedAt||dates.manualCostUpdatedAt||dates.etStorageDetailUpdatedAt||dates.etStorageUpdatedAt||dates.manualStorageUpdatedAt||'';const items=[['BI 页面生成',fmtStamp(genAt())],['SHEIN 销售源',fmtStamp(dates.salesUpdatedAt||dates.salesDate)],['SHEIN 业务域',fmtStamp(dates.businessUpdatedAt||dates.businessDate)],['SHEIN 链接表现',fmtStamp(dates.linkUpdatedAt||dates.linkDate)],['成本表文件',fmtStamp(costTs)],['ET 货代仓',fmtStamp(dates.etUpdatedAt)],['数据体检',auditHtml()]];return`<section class="status-strip">${items.map(([k,v])=>`<div><strong>${H(k)}</strong><span>${String(v).includes('<span')?v:H(v)}</span></div>`).join('')}</section>`}

function home(){ensure('home',true);const storeBySales=storeRanks(),storeByQty=storeQtyRanks(),productBySales=productRanks(),productByQty=productQtyRanks();return`${healthStrip()}${homeKpis()}${head('趋势','按钮只切换当前趋势指标；页面只保留一个日图和一个月图，图上直接显示关键数字。',trendMetricButtons())}<div class="trend-stack">${trendPanel('day')}${trendPanel('month')}</div>${head('排行榜','保留 V1 的店铺/产品净成交额与净销量四块信息，并恢复条形比例图。',chips(homeNeeds()))}<section class="rank-grid"><div class="panel rank-panel"><h4>店铺净成交额排行</h4><p class="sub">当前范围 ${M(storeBySales.length)} 店 · ${H(selectedRangeText())}</p>${homeRankList(storeBySales,{color:it=>it.color||'#10b981',attr:it=>`data-home-store="${H(it.key)}"`})}</div><div class="panel rank-panel"><h4>店铺净销量排行</h4><p class="sub">按净成交销量件数排序。</p>${homeRankList(storeByQty,{color:it=>it.color||'#60a5fa',attr:it=>`data-home-store="${H(it.key)}"`})}</div><div class="panel rank-panel"><h4>产品净成交额排行</h4><p class="sub">标准货号归并，展示均价、销量、订单、覆盖店和天数。</p>${homeRankList(productBySales,{className:'product-rank',color:()=> '#db2777',attr:it=>`data-home-product="${H(it.key)}"`})}</div><div class="panel rank-panel"><h4>产品净销量排行</h4><p class="sub">按净成交销量件数排序。</p>${homeRankList(productByQty,{className:'product-rank',color:()=> '#a855f7',attr:it=>`data-home-product="${H(it.key)}"`})}</div></section>`}

function ordersPage(){ensure('orders',true);if(!A(D.orders).length&&SS.orders?.status!=='ok')return intro('订单中心','按订单创建时间查看成交、取消、履约和 COD/payment 标记。')+wait('orders');
const rs=orders().slice().sort((a,b)=>String(dt(b)).localeCompare(dt(a))).slice(0,300);return intro('订单中心','以订单创建时间为主口径，后续承接 COD、履约和异常订单钻取。')+`<section class="kpis"><div class="stat"><div class="stat-label">订单数</div><div class="stat-value">${M(uniq(orders().map(r=>r.order_no||r.bill_no)).length)}</div><div class="stat-note">当前筛选订单</div></div><div class="stat"><div class="stat-label">销售额</div><div class="stat-value">${M(sum(orders(),['sales_sar']))} SAR</div><div class="stat-note">订单明细金额</div></div><div class="stat"><div class="stat-label">件数</div><div class="stat-value">${M(sum(orders(),['quantity']))}</div><div class="stat-note">订单商品件数</div></div><div class="stat"><div class="stat-label">COD 标记</div><div class="stat-value">${M(orders().filter(r=>r.is_cod===true||r.is_cod===1||/COD/i.test(String(r.payment_method||r.tags||''))).length)}</div><div class="stat-note">严格分母走云端 payment flag</div></div></section>`+panel('订单明细','默认展示最近 300 行，后续接服务端分页。',['日期','店铺','订单','货号','金额','件数','状态'],rs.map(r=>[dt(r),sk(r),r.order_no||r.bill_no,prod(r),M2(r.sales_sar),M(r.quantity),r.goods_performance_status_desc||r.order_status||'']))}

function returnsPage(){ensure('returns',true);if(!A(D.afterSales).length&&SS.afterSales?.status!=='ok')return intro('退货退款中心','按售后申请时间和订单创建时间双口径拆解售后。')+wait('afterSales');
const rs=returns().slice().sort((a,b)=>String(dt(b)).localeCompare(dt(a))).slice(0,300);
const by=Array.from(grp(returns(),r=>String(r.reason_names||r.reason||'未标注')),([key,x])=>({key,label:key,value:sum(x,['amount_sar','price_amount_total']),sub:`${M(x.length)} 条 · ${M(sum(x,['quantity']))} 件`})).sort((a,b)=>b.value-a.value);return intro('退货退款中心','售后申请时间用于异常发现；订单创建时间用于成熟窗口比例复盘。')+`<section class="kpis"><div class="stat"><div class="stat-label">售后金额</div><div class="stat-value">${M(sum(returns(),['amount_sar','price_amount_total']))} SAR</div><div class="stat-note">当前筛选</div></div><div class="stat"><div class="stat-label">售后单</div><div class="stat-value">${M(returns().length)}</div><div class="stat-note">申请记录</div></div><div class="stat"><div class="stat-label">COD未妥投</div><div class="stat-value">${M(returns().filter(r=>/COD未妥投/.test(String(r.reason_names||''))).length)}</div><div class="stat-note">比例分母走云端订单标记</div></div><div class="stat"><div class="stat-label">涉及货号</div><div class="stat-value">${M(uniq(returns().map(pkey)).length)}</div><div class="stat-note">标准货号</div></div></section><section class="grid two"><div class="panel"><h4>原因排行</h4>${rank(by,'reason')}</div><div>${panel('售后明细','默认展示最近 300 行。',['申请时间','店铺','订单','货号','金额','原因'],rs.map(r=>[r.request_time||dt(r),sk(r),r.order_no,prod(r),M2(r.amount_sar||r.price_amount_total),r.reason_names||r.resolution_plan_name||'']))}</div></section>`}

function pmatrix(){const map=new Map();
const en=(k,n)=>{k=k||n||'-';if(!map.has(k))map.set(k,{key:k,name:n||k,stores:new Map(),tot:{wait:0,on:0,sold:0,off:0}});return map.get(k)};for(const r of matrix()){const p=en(pkey(r),prod(r)),s=sk(r);if(!s)continue;
const c=p.stores.get(s)||{wait:0,on:0,sold:0,off:0};c.wait+=N(r.wait_shelf_count);c.on+=N(r.on_shelf_count);c.sold+=N(r.sold_out_count);c.off+=N(r.out_shelf_count||r.off_shelf_count);p.stores.set(s,c)}for(const r of links()){const p=en(pkey(r),prod(r)),s=sk(r);if(!s)continue;
const c=p.stores.get(s)||{wait:0,on:0,sold:0,off:0},st=String(r.shelf_status_name||r.health_bucket||'').toLowerCase();if(r.is_wait_shelf||/待上架/.test(st))c.wait++;else if(r.is_on_shelf||/已上架|上架/.test(st))c.on++;else if(/售罄/.test(st))c.sold++;else if(/下架|淘汰|退役/.test(st))c.off++;p.stores.set(s,c)}for(const p of map.values())for(const c of p.stores.values()){p.tot.wait+=c.wait;p.tot.on+=c.on;p.tot.sold+=c.sold;p.tot.off+=c.off}return Array.from(map.values()).filter(p=>p.tot.wait+p.tot.on+p.tot.sold+p.tot.off>0).sort((a,b)=>(b.tot.on+b.tot.wait)-(a.tot.on+a.tot.wait)).slice(0,120)}

function productsPage(){ensure('products',true);if(!A(D.matrix).length&&!A(D.storeLinks).length&&SS.linksData?.status!=='ok')return intro('商品列表','标准货号 × 店铺，上架状态矩阵。')+wait('linksData');
const rs=pmatrix(),st=stores.filter(x=>S.scope==='ALL'?true:scopeStores().has(x));
const body=rs.length?`<div class="table-wrap"><div class="status-grid" style="--cols:${st.length}"><div class="cell headcell">标准货号</div>${st.map(s=>`<div class="cell headcell">${H(s)}</div>`).join('')}${rs.map(p=>`<div class="cell product">${H(p.name)}<div class="tiny">待 ${p.tot.wait} · 上 ${p.tot.on} · 售罄 ${p.tot.sold} · 下 ${p.tot.off}</div></div>${st.map(s=>{const c=p.stores.get(s)||{wait:0,on:0,sold:0,off:0};return`<div class="cell"><div class="counts"><span class="wait" title="待上架">${c.wait}</span><span class="on" title="已上架">${c.on}</span><span class="sold" title="已售罄">${c.sold}</span><span class="off" title="已下架">${c.off}</span></div></div>`}).join('')}`).join('')}</div></div>`:'<div class="empty">当前筛选没有商品链接状态。</div>';return intro('商品列表','参考 SHEIN 商品列表：按标准货号归并，横向看每个店待上架、已上架、已售罄、已下架数量。')+head('上架状态矩阵','每格四个数依次为：待上架 / 已上架 / 已售罄 / 已下架。',chips(['linksData']))+`<section class="panel">${body}</section>`}

function inventoryPage(){ensure('inventory',true);
const ps=invProducts().slice().sort((a,b)=>N(a.days_of_supply_with_incoming)-N(b.days_of_supply_with_incoming));
const tr=trendFirst(invTrend(),['platform_display_stock','usable_inventory','inventory_quantity']);return intro('库存管理','分清三套口径：前台展示库存趋势、ET 可售、成本表供给与去化周期。')+`<section class="kpis"><div class="stat"><div class="stat-label">ET可售</div><div class="stat-value">${M(sum(ps,['et_estimated_available_qty']))}</div><div class="stat-note">ET 货代仓可售估算</div></div><div class="stat"><div class="stat-label">成本表在库</div><div class="stat-value">${M(sum(ps,['estimated_on_hand_quantity']))}</div><div class="stat-note">到仓批次 - 已售</div></div><div class="stat"><div class="stat-label">成本表在途</div><div class="stat-value">${M(sum(ps,['incoming_quantity']))}</div><div class="stat-note">已发未到/待确认</div></div><div class="stat"><div class="stat-label">成本表供给</div><div class="stat-value">${M(sum(ps,['estimated_total_supply_quantity']))}</div><div class="stat-note note">成本表供给 = 到仓 + 在途 - 已售；不等于 ET可售 + 在途。</div></div></section>${head('库存趋势','来自前台展示库存快照；进入库存页才按需加载。',chips(['inventoryTrend']))}<section class="panel">${invTrend().length?chart(tr):wait('inventoryTrend','正在加载云端库存趋势 section…')}</section>`+panel('去化周期','按成本表供给和近 7/30 天速度估算。备注保持小字号。',['货号','ET可售','成本表在库','在途','成本表供给','近30天销量','去化周期','说明'],ps.slice(0,200).map(r=>[prod(r),M(r.et_estimated_available_qty),M(r.estimated_on_hand_quantity),M(r.incoming_quantity),M(r.estimated_total_supply_quantity),M(r.gross_sold_30d),M2(r.days_of_supply_with_incoming||r.days_of_supply_on_hand),`<span class="note">${H(r.stock_status||r.risk_level||'')}</span>`]))}

function trafficPage(){ensure('traffic',true);if(!A(D.productTrafficDaily).length&&SS.productTrafficDaily?.status!=='ok')return intro('流量数据','目标粒度：日期 × 店铺 × 标准货号。')+wait('productTrafficDaily','正在加载云端货号级每日流量 section…');
const rs=traffic(),by=Array.from(grp(rs,r=>pkey(r)),([key,x])=>({key,label:prod(x[0]),value:sumFirst(x,['eps_uv','exposure_uv','exposure_cnt']),sub:`访客 ${M(sumFirst(x,['goods_uv','uv','visitor_cnt']))} · 成交 ${M(sumFirst(x,['sale_cnt','pay_order_cnt','quantity']))}`})).sort((a,b)=>b.value-a.value);
const exp=sumFirst(rs,['eps_uv','exposure_uv','exposure_cnt']),uv=sumFirst(rs,['goods_uv','uv','visitor_cnt']),pay=sumFirst(rs,['sale_cnt','pay_order_cnt','quantity']);return intro('流量数据','货号级每日流量必须精确到日期 × 店铺 × 标准货号，并在当前筛选下重算曝光、访客、成交和转化。')+`<section class="kpis"><div class="stat"><div class="stat-label">曝光</div><div class="stat-value">${M(exp)}</div><div class="stat-note">当前筛选汇总</div></div><div class="stat"><div class="stat-label">访客</div><div class="stat-value">${M(uv)}</div><div class="stat-note">点击率 ${exp?PCT(uv/exp):'—'}</div></div><div class="stat"><div class="stat-label">成交件数</div><div class="stat-value">${M(pay)}</div><div class="stat-note">支付率 ${uv?PCT(pay/uv):'—'}</div></div><div class="stat"><div class="stat-label">明细粒度</div><div class="stat-value">${M(rs.length)}</div><div class="stat-note note">每行应对应日期 × 店铺 × 标准货号；大表按需加载，不拖慢首页。</div></div></section>${head('每日曝光趋势','只保留一个图，绝对量趋势和比例指标分开看。',chips(['productTrafficDaily']))}<section class="panel">${chart(trendFirst(rs,['eps_uv','exposure_uv','exposure_cnt']))}</section><section class="grid two"><div class="panel"><h4>货号流量排行</h4>${rank(by,'product')}</div><div>${panel('流量明细','默认展示 300 行。',['日期','店铺','货号','曝光','访客','成交','点击率','支付率'],rs.slice(0,300).map(r=>[dt(r),sk(r),prod(r),M(firstNum(r,['eps_uv','exposure_uv','exposure_cnt'])),M(firstNum(r,['goods_uv','uv','visitor_cnt'])),M(firstNum(r,['sale_cnt','pay_order_cnt','quantity'])),PCT(N(r.click_rate)||(N(r.goods_uv)/Math.max(1,N(r.eps_uv)))),PCT(N(r.pay_rate)||(N(r.sale_cnt)/Math.max(1,N(r.goods_uv))))]))}</div></section>`}
function reviewsPage(){ensure('reviews',true);if(!A(D.comments).length&&SS.comments?.status!=='ok')return intro('商品评价','低星、质量投诉、中文译文。')+wait('comments');
const rs=F(D.comments||[]).slice().sort((a,b)=>String(dt(b)).localeCompare(dt(a))).slice(0,300);return intro('商品评价','按货号和店铺定位差评、质量投诉和说明书/物流问题。')+panel('评价明细','优先展示平台中文译文。',['日期','店铺','货号','星级','中文译文','原文'],rs.map(r=>[dt(r),sk(r),prod(r),r.goods_comment_star_name||r.goods_comment_star,r.goods_comment_content_zh||'',r.goods_comment_content||'']))}

